package java.util.regex;
public class PatternSyntaxException extends IllegalArgumentException {private final String description,pattern;private final int index;public PatternSyntaxException(String description){this(description,null,-1);}public PatternSyntaxException(String description,String regex,int index){super(description);this.description=description;this.pattern=regex;this.index=index;}public int getIndex(){return index;}public String getDescription(){return description;}public String getPattern(){return pattern;}public String getMessage(){StringBuilder b=new StringBuilder(description);if(index>=0)b.append(" near index ").append(index);b.append('\n').append(pattern);if(index>=0){b.append('\n');for(int i=0;i<index;i++)b.append(' ');b.append('^');}return b.toString();}}
